import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadMalabarFrogData(){const e=readFileSync(resolve(__dirname,"../../malabar-gliding-frog-explorer/malabar-frog-data.js"),"utf-8");return new Function(e+"\nreturn { MALABAR_FROG_INFO, TAXONOMY_DATA, ECOLOGY_BEHAVIOUR, INTERESTING_FACTS, GALLERY_IMAGES, REFERENCES };")()}describe("Malabar Gliding Frog Explorer — Data Tests",()=>{let e;beforeAll(()=>{e=loadMalabarFrogData()}),describe("MALABAR_FROG_INFO metadata",()=>{it("contains correct species metadata and Western Ghats endemism",()=>{expect(e.MALABAR_FROG_INFO.id).toBe("malabar-gliding-frog"),expect(e.MALABAR_FROG_INFO.scientificName).toBe("Rhacophorus malabaricus"),expect(e.MALABAR_FROG_INFO.endemicRegion).toContain("Western Ghats"),expect(e.MALABAR_FROG_INFO.iucnStatus).toContain("Least Concern")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.MALABAR_FROG_INFO.quickStats)).toBe(!0),expect(e.MALABAR_FROG_INFO.quickStats.length).toBe(6)})}),describe("TAXONOMY_DATA",()=>{it("contains valid amphibian taxonomy classification",()=>{expect(e.TAXONOMY_DATA.class).toBe("Amphibia"),expect(e.TAXONOMY_DATA.family).toBe("Rhacophoridae"),expect(e.TAXONOMY_DATA.genus).toBe("Rhacophorus")})}),describe("ECOLOGY_BEHAVIOUR",()=>{it("contains required sections",()=>{expect(e.ECOLOGY_BEHAVIOUR.overview).toBeDefined(),expect(e.ECOLOGY_BEHAVIOUR.distribution).toBeDefined(),expect(e.ECOLOGY_BEHAVIOUR.habitat).toBeDefined(),expect(e.ECOLOGY_BEHAVIOUR.behaviour).toBeDefined(),expect(e.ECOLOGY_BEHAVIOUR.ecologicalImportance).toBeDefined(),expect(e.ECOLOGY_BEHAVIOUR.conservation).toBeDefined()})}),describe("INTERESTING_FACTS & GALLERY",()=>{it("has non-empty facts and gallery images",()=>{expect(Array.isArray(e.INTERESTING_FACTS)).toBe(!0),expect(e.INTERESTING_FACTS.length).toBeGreaterThanOrEqual(4),expect(Array.isArray(e.GALLERY_IMAGES)).toBe(!0),expect(e.GALLERY_IMAGES.length).toBeGreaterThanOrEqual(2)})})});